        StyleComponent::HeaderFilename => {
            let prefix = description
                .kind()
                .map(|kind| format!("{}: ", kind))
                .unwrap_or_else(|| "".into());
            let title = description.title();

            // The width available for header content on each line,
            // taking the panel (and the grid border) into account.
            let indent_width = self.panel_width
                + if self.config.style_components.grid() && self.panel_width > 0 {
                    2
                } else {
                    0
                };
            let wrap_width = self.config.term_width.saturating_sub(indent_width);

            let wrapping_enabled = !matches!(
                self.config.wrapping_mode,
                WrappingMode::NoWrapping(true)
            ) && wrap_width > 0;

            if !wrapping_enabled {
                writeln!(
                    handle,
                    "{}{}{}",
                    prefix,
                    self.colors.header_value.paint(title),
                    mode
                )
            } else {
                let prefix_width: usize = prefix
                    .chars()
                    .map(|c| self.measure_display_width(c))
                    .sum();

                let mut line_buf = String::with_capacity(wrap_width);
                let mut line_width = 0;
                let mut max_width = wrap_width.saturating_sub(prefix_width);

                write!(handle, "{}", prefix)?;

                for c in title.chars() {
                    let char_width = self.measure_display_width(c);

                    if line_width + char_width > max_width {
                        writeln!(handle, "{}", self.colors.header_value.paint(&line_buf))?;
                        self.print_header_component_indent(handle)?;
                        line_buf.clear();
                        line_width = 0;
                        max_width = wrap_width;
                    }

                    line_buf.push(c);
                    line_width += char_width;
                }

                write!(handle, "{}{}", self.colors.header_value.paint(&line_buf), mode)?;
                writeln!(handle)
            }
        }

